private static void moveFromWithPriorCandidates(final Set<SubRuleContext> candidateSubRuleIds, final NameState fromState, final Patterns fromPattern, final int tokenIndex, final Task task, final SubRuleContext.Generator subRuleContextGenerator) {
    Set<SubRuleContext> candidateSubRuleIdsForNextStep = calculateCandidateSubRuleIdsForNextStep(candidateSubRuleIds, fromState, fromPattern);
    // If there are no more candidate sub-rules, there is no need to proceed further.
    if (candidateSubRuleIdsForNextStep != null && !candidateSubRuleIdsForNextStep.isEmpty()) {
        moveFrom(candidateSubRuleIdsForNextStep, fromState, tokenIndex, task, subRuleContextGenerator);
    }
}
